(()=>{
  const C=Cimora,{S,M,E,ui,btn,link,art,badge,money,path}=C;
  const labels={story:'故事输入',cast:'角色身份',world:'空间与光线',prop:'道具连续性',boards:'构图与对白',sketch:'视觉候选',final:'画面定稿',layout:'阅读节奏',shots:'剧情与镜头',voice:'独立配音 · 可选',motion:'动作与原生声音',review:'人工确认',export:'版本快照'};
  const picture={cast:1,world:0,prop:3,sketch:6,final:8,motion:6};
  function edges(e){return e.graph.edges.map(x=>{const a=e.graph.nodes.find(n=>n.id===x.from),b=e.graph.nodes.find(n=>n.id===x.to);if(!a||!b)return '';return `<path data-from="${a.id}" data-to="${b.id}" d="${curve(a,b)}" class="${a.status==='done'?'ready':''}" marker-end="url(#cm-arrow)"/>`;}).join('');}
  function curve(a,b){const x=a.x+240,y=a.y+90,ex=b.x,ey=b.y+90,d=Math.max(65,Math.abs(ex-x)*.5);return `M ${x} ${y} C ${x+d} ${y}, ${ex-d} ${ey}, ${ex} ${ey}`;}
  function node(e,n){const selected=e.selected===n.id;return `<article class="cm-graph-node ${selected?'selected':''} ${n.status}" data-node-id="${n.id}" style="left:${n.x}px;top:${n.y}px"><button class="cm-port input" data-cm="link-to" data-node="${n.id}" aria-label="连接到 ${E(n.title)}"></button><header class="cm-node-drag" data-node-drag="${n.id}"><span>${M.defs[n.kind]?.[1]||'◇'}</span><strong>${E(n.title)}</strong><small>⋮⋮</small></header><button class="cm-node-body" data-cm="select-node" data-node="${n.id}">${picture[n.kind]!==undefined?art(picture[n.kind],n.title):`<div class="cm-node-text">${E(n.kind==='story'?e.script.slice(0,58):n.kind==='boards'?e.boards.length+' 个分格 · 图文与顺序绑定':n.kind==='voice'?'需要额外配音时再使用':n.kind==='export'?'采用版本与交付快照':labels[n.kind]||'自由创作分支')}</div>`}<div class="cm-node-footer">${badge(n.status)}<span>v${n.version} ${n.version>n.adopted?'· 候选':''}</span></div></button><button class="cm-port output" data-cm="link-from" data-node="${n.id}" aria-label="从 ${E(n.title)} 连线"></button></article>`;}
  function inspector(c){const n=c.e.graph.nodes.find(n=>n.id===c.e.selected)||c.e.graph.nodes[0];if(!n)return '';const deps=c.e.graph.edges.filter(x=>x.to===n.id).map(x=>c.e.graph.nodes.find(n=>n.id===x.from));return `<aside class="cm-canvas-inspector"><div class="cm-panel-title"><span class="cm-kicker">NODE INSPECTOR</span>${badge(n.status)}</div><h3>${E(n.title)}</h3><p>${labels[n.kind]||'自定义制作分支'}</p>${picture[n.kind]!==undefined?art(picture[n.kind],n.title,'cm-inspector-art'):''}<div class="cm-detail-lines"><span>供应能力<b>${E(n.provider)}</b></span><span>运行预估<b>${money(n.cost)} 示例</b></span><span>当前候选<b>v${n.version}</b></span><span>已采用<b>v${n.adopted}</b></span></div><h4>依赖输入</h4><div class="cm-dependency-list">${deps.map(d=>`<div><span>${E(d?.title)}</span>${btn('×','unlink','cm-icon-button',`data-from="${d?.id}" data-to="${n.id}" aria-label="移除依赖 ${E(d?.title)}"`)}</div>`).join('')||'<p>没有上游依赖</p>'}</div>${ui.canvasLink?`<div class="cm-notice">已选择起点：${E(c.e.graph.nodes.find(n=>n.id===ui.canvasLink)?.title)}<br>点击目标节点左侧圆点完成关联。${btn('取消连线','cancel-link','cm-text-link')}</div>`:''}<div class="cm-inspector-actions">${btn('▷ 运行到此步骤','run-node','cm-button primary full',`data-node="${n.id}"`)}${n.status==='done'&&n.version>n.adopted?btn('✓ 采用当前候选','adopt-node','cm-button ghost full',`data-node="${n.id}"`):''}${btn('打开详细编辑','node-edit','cm-button ghost full',`data-node="${n.id}"`)}${btn('查看变更影响','node-impact','cm-button ghost full',`data-node="${n.id}"`)}${n.id.includes('-')?btn('移除此分支','delete-node','cm-text-link',`data-node="${n.id}"`):''}</div><small class="cm-help">连线表达依赖，移动位置不改变阅读顺序。候选不会静默替换已采用版本。</small></aside>`;}
  function canvas(c){const v=c.e.graph.viewport;return `<section class="cm-canvas-shell"><div class="cm-canvas-toolbar"><div><span class="cm-kicker">STORY GRAPH</span><strong>让灵感，自由连接。</strong></div><div>${btn('＋ 添加节点','add-node','cm-button ghost small')}${btn('自动整理','auto-layout','cm-button ghost small')}${btn('适应画布','fit-canvas','cm-button ghost small')}</div></div><div class="cm-canvas-layout"><div class="cm-canvas-viewport" id="cm-canvas-viewport" tabindex="0" aria-label="无限画布，可拖动空白平移，滚轮缩放"><div class="cm-canvas-world" style="transform:translate(${v.x}px,${v.y}px) scale(${v.zoom})"><svg class="cm-graph-edges" width="3200" height="1800" aria-hidden="true"><defs><marker id="cm-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#8471bc"/></marker></defs>${edges(c.e)}</svg>${c.e.graph.nodes.map(n=>node(c.e,n)).join('')}</div><div class="cm-canvas-help">拖动空白平移 · 滚轮缩放 · 拖动卡片标题移动 · 两侧圆点连线</div><div class="cm-zoom-controls">${btn('−','zoom-out','cm-icon-button','aria-label="缩小画布"')}<span id="cm-zoom-label">${Math.round(v.zoom*100)}%</span>${btn('＋','zoom-in','cm-icon-button','aria-label="放大画布"')}</div><div class="cm-mini-map"><span>CHAPTER MAP</span><svg viewBox="0 0 2600 1000">${c.e.graph.nodes.map(n=>`<rect x="${n.x}" y="${n.y}" width="210" height="150" fill="${n.id===c.e.selected?'#b6a1ff':n.status==='done'?'#6baf9a':'#57476e'}" rx="15"/>`).join('')}</svg></div></div>${inspector(c)}</div></section>`;}
  function runs(c){const e=c.e,r=e.run,counts=s=>e.graph.nodes.filter(n=>n.status===s).length;return `<div class="cm-page-heading"><div><span class="cm-kicker">PRODUCTION CONTROL</span><h1>把每一步，安排妥当。</h1><p>${E(c.p.name)} / ${E(c.c.title)} · 根据依赖执行，按章节控制预算。</p></div><div>${link('返回创作',path(c,e.stage),'cm-button ghost')}${btn('▷ 运行制作','run-plan','cm-button primary')}</div></div>${C.scopePicker(c,'cm-runs')}<div class="cm-run-stats"><article><span>本章已用 / 预算</span><strong>${money(e.spent)} <small>/ ${money(e.budget)}</small></strong>${btn('调整预算','budget','cm-text-link')}</article><article><span>就绪步骤</span><strong>${counts('done')} <small>/ ${e.graph.nodes.length}</small></strong><p>保留成功结果</p></article><article><span>失败 / 来源更新</span><strong>${counts('failed')} <small>/ ${counts('stale')}</small></strong><p>只重做受影响步骤</p></article><article><span>并发任务</span><strong>${e.concurrency}<small> 个</small></strong><p>示例模型预算与队列</p></article></div><div class="cm-run-grid"><section class="cm-panel"><div class="cm-panel-title"><h3>章节依赖队列</h3>${r?badge(r.status,r.status==='running'?'批次进行中':r.status==='paused'?'批次已暂停':r.status==='failed'?'等待失败恢复':r.status==='done'?'批次完成':'等待输入'):'<span>尚未开始新批次</span>'}</div>${e.graph.nodes.map(n=>C.nodeCard(c,n)).join('')}<div class="cm-run-controls">${r&&r.status==='running'?btn('Ⅱ 暂停队列','pause-run','cm-button ghost'):r?.status==='paused'?btn('▷ 继续队列','resume-run','cm-button primary'):''}${r&&['failed','blocked'].includes(r.status)?btn('↻ 仅重试失败与未完成步骤','retry-run','cm-button primary'):''}${r&&['running','paused'].includes(r.status)?btn('停止后续任务','cancel-run','cm-button ghost'):''}</div></section><aside><section class="cm-panel"><span class="cm-kicker">RUN POLICY</span><h3>让 API 服务于你的创作。</h3><p>文本、图像、语音、视频分别编排。上游失败时暂停依赖步骤，成功结果不重复生成。</p><label class="cm-label">最大并发<select data-cm-change="concurrency"><option ${e.concurrency===1?'selected':''}>1</option><option ${e.concurrency===2?'selected':''}>2</option><option ${e.concurrency===3?'selected':''}>3</option></select></label><label class="cm-check"><input type="checkbox" data-cm-change="fail-demo" ${e.failDemo?'checked':''}>体验视频 API 超时与恢复</label><small class="cm-help">开启后首次动态镜头任务模拟失败；重试可恢复。所有费用为示例，无真实 API 调用。</small></section><section class="cm-panel cm-execution-log"><h3>工程事件</h3>${e.events.slice(0,10).map(ev=>`<div><i></i><strong>${E(ev.text)}</strong><p>${E(ev.detail)}</p><time>${new Date(ev.time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')||'<p>创建、修改、运行与采用后，记录会出现在这里。</p>'}</section></aside></div>`;}
  function transform(c){const w=S.$('.cm-canvas-world'),v=c.e.graph.viewport;if(w)w.style.transform=`translate(${v.x}px,${v.y}px) scale(${v.zoom})`;if(S.$('#cm-zoom-label'))S.$('#cm-zoom-label').textContent=Math.round(v.zoom*100)+'%';}
  function bindCanvas(){const root=S.$('#cm-canvas-viewport');if(!root)return;const c=C.ctx();let drag=null,moved=false;
    root.addEventListener('pointerdown',ev=>{if(ev.button!==0||ev.target.closest('button,input,select'))return;const handle=ev.target.closest('[data-node-drag]');const node=handle?c.e.graph.nodes.find(n=>n.id===handle.dataset.nodeDrag):null;if(ev.target.closest('.cm-graph-node')&&!node)return;drag={x:ev.clientX,y:ev.clientY,node,nx:node?.x,ny:node?.y,vx:c.e.graph.viewport.x,vy:c.e.graph.viewport.y};moved=false;root.setPointerCapture(ev.pointerId);root.classList.add('dragging');ev.preventDefault();});
    root.addEventListener('pointermove',ev=>{if(!drag)return;const dx=ev.clientX-drag.x,dy=ev.clientY-drag.y;moved=Math.abs(dx)+Math.abs(dy)>4;if(drag.node){const n=drag.node;n.x=Math.max(0,Math.min(2800,drag.nx+dx/c.e.graph.viewport.zoom));n.y=Math.max(0,Math.min(1500,drag.ny+dy/c.e.graph.viewport.zoom));const el=root.querySelector(`[data-node-id="${n.id}"]`);el.style.left=n.x+'px';el.style.top=n.y+'px';root.querySelectorAll('.cm-graph-edges path[data-from]').forEach(p=>{const a=c.e.graph.nodes.find(n=>n.id===p.dataset.from),b=c.e.graph.nodes.find(n=>n.id===p.dataset.to);p.setAttribute('d',curve(a,b));});}else{c.e.graph.viewport.x=drag.vx+dx;c.e.graph.viewport.y=drag.vy+dy;transform(c);}});
    const end=()=>{if(!drag)return;drag=null;root.classList.remove('dragging');M.save();};root.addEventListener('pointerup',end);root.addEventListener('pointercancel',end);
    root.addEventListener('wheel',ev=>{ev.preventDefault();const v=c.e.graph.viewport,r=root.getBoundingClientRect(),px=ev.clientX-r.left,py=ev.clientY-r.top,z=Math.max(.22,Math.min(1.6,v.zoom*(ev.deltaY<0?1.1:.9)));v.x=px-(px-v.x)*z/v.zoom;v.y=py-(py-v.y)*z/v.zoom;v.zoom=z;transform(c);M.save();},{passive:false});
  }
  C.canvas=canvas;C.runs=runs;C.bindCanvas=bindCanvas;C.canvasTransform=transform;
})();
